"use client";

import { PageHeader } from "@/components/app/page-header";
import { EmptyState } from "@/components/app/empty-state";
import { Bell } from "lucide-react";

export function NotificationsView() {
  return (
    <div className="space-y-6">
      <PageHeader title="Thông báo" description="Tất cả thông báo và cảnh báo hệ thống" icon={<Bell className="h-5 w-5" />} />
      <EmptyState
        icon={<Bell className="h-6 w-6" />}
        title="Thông báo chưa được backend hỗ trợ"
        description="Backend hiện chưa cung cấp API đọc hoặc cập nhật trạng thái thông báo."
      />
    </div>
  );
}
